import { ToolDefinition } from "../types/index.js";
import { callNetsuiteRestlet } from "../utils/api.js";
import { getEnvironmentConfig } from "../utils/config.js";

export const getRunFunctionLogsTool: ToolDefinition = {
    name: "netsuite_get_run_function_logs",
    description:
        "Retrieve the last 500 execution logs generated by calls to netsuite_run_function. " +
        "Because netsuite_run_function executes inside the MCP RESTlet context rather than the target script record, " +
        "always pair this tool with netsuite_run_function to inspect logs from that execution.",
    meta: {
        isDestructive: false,
        requiresSdf: false
    },
    inputSchema: {
        type: "object",
        properties: {}
    },
    execute: async () => {
        try {
            const { config } = await getEnvironmentConfig();
            const payload = {
                action: "SCRIPT_LOGS_BY_ID",
                scriptId: config.scriptId,
                deploymentId: config.deploymentId
            };
            const response = await callNetsuiteRestlet(payload);
            return { content: [{ type: "text", text: JSON.stringify(response, null, 2) }] };
        } catch (error: any) {
            return { content: [{ type: "text", text: `RESTlet Execution Error: ${error.message}` }] };
        }
    }
};
